void build_route_key(char *key, size_t key_size, const char *version) {
    const char *base_path = "/microservice/api";
    size_t base_len = strlen(base_path);

    // 检查key是否为空指针
    if (key == NULL) {
        return;
    }

    // 初始化key为清空状态
    key[0] = '\0';

    // 检查version是否为空指针
    if (version == NULL) {
        // 如果version为空，则只使用基础路径
        if (key_size > base_len) {
            strcpy(key, base_path);
        } else {
            // 如果缓冲区不够大，复制尽可能多的字符
            strncpy(key, base_path, key_size - 1);
            key[key_size - 1] = '\0';
        }
        return;
    }

    // 计算版本号长度
    size_t version_len = strlen(version);

    // 检查是否有足够的空间存储基础路径、版本号和分隔符
    if (key_size <= base_len + version_len + 1) { // +1 for the '/' separator
        // 如果空间不够，尽可能多地复制基础路径
        if (key_size > base_len) {
            strncpy(key, base_path, key_size - 2); // -2 to leave space for '/' and '\0'
            key[key_size - 2] = '\0';
        } else {
            strncpy(key, base_path, key_size - 1);
            key[key_size - 1] = '\0';
        }
        return;
    }

    // 复制基础路径
    strcpy(key, base_path);

    // 添加分隔符
    strcat(key, "/");

    // 添加版本号
    strcat(key, version);
}
